import { createFileRoute } from '@tanstack/react-router';
import { HomeMain } from '../slots/defs/homeMain';

// The home page. A page is a file under routes/ — `createFileRoute('<its url>')` — with its nav
// link under features/. Its panels fill the home.main slot.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  return (
    <>
      <p data-testid="home-empty">Nothing here yet.</p>
      <HomeMain.Slot />
    </>
  );
}
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { defineSlot } from '../Slot';

/**
 * The shell's nav bar. Every page contributes its own link — the shell never lists the pages.
 * A nav link carries `data-testid="nav-<section>"` (the test contract; CLAUDE.md).
 */
export const AppNav = defineSlot('app.nav');
import { defineSlot } from '../Slot';

/**
 * The shell's session bar: who is signed in and which sheet is active. Filled by
 * features/session/ — the sign-in form, then the sheet picker once someone is signed in.
 */
export const AppSession = defineSlot('app.session');
import { defineSlot } from '../Slot';

/** The home page's main region: the panels kept per sheet (people, ...). */
export const HomeMain = defineSlot('home.main');
import { defineSlot } from '../Slot';

/** Controls shown on the people list, above the table (e.g. the quick-add bar). */
export const PeopleBar = defineSlot('people.bar');
import { defineSlot } from '../Slot';

/** Extra column headers of the people table, one per contributed column. */
export const PersonColumns = defineSlot('person.columns');

/** Extra cells of a person's row (in the same order as their PersonColumns headers). */
export const PersonCells = defineSlot<{ personId: number }>('person.cells');
import { useState } from 'react';
import type { FormEvent } from 'react';
import { HttpError } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleBar } from '../../slots/defs/peopleBar';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { useClaims } from '../claims/claims';
import { GRADES, addPerson, peopleKey, updatePerson, useEditingPerson, usePeople, useShowRetired } from './people';
import type { Person, PersonInput } from './people';

const EMPTY: PersonInput = { name: '', grade: 'A' };

// The sheet's people: a form that adds a person or, once a person's editor is opened, edits them;
// and the list of people in the order they were added. Retired people are left out unless "show
// retired" is on — except one who still has a DRAFT claim, who stays listed until it is dealt with.
// Each save records the grade from the form's from-date (default the sheet's today), keeping the grades
// already recorded; a person's first grade applies from the beginning of time. The list shows the grade
// in force on the sheet's today.
// The editor remembers the version it loaded: when someone else has saved the person since, the save
// is refused and the form shows their values.
function People() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const today = useSheetToday();
  const people = usePeople();
  const claims = useClaims().data ?? [];
  const [showRetired] = useShowRetired();
  const [editing, setEditing] = useEditingPerson();
  const [form, setForm] = useState<PersonInput>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (input: PersonInput) =>
      editing ? updatePerson(sheet!, user, Number(editing), input) : addPerson(sheet!, user, input),
    onSuccess: async () => {
      setForm(EMPTY);
      setEditing(undefined);
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet!) });
    },
    onError: async (e) => {
      if (!(editing && e instanceof HttpError && e.status === 409)) {
        setError('The person could not be saved: a name is required and must not already be in use.');
        return;
      }
      setError('Someone else saved this person meanwhile; their values are shown. Nothing was saved.');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet!) });
      const current = queryClient.getQueryData<Person[]>(peopleKey(sheet!))?.find((p) => p.id === Number(editing));
      if (current) setForm({ name: current.name, grade: current.grade ?? 'A', version: current.version });
    },
  });

  if (!sheet) return null;

  const hasDraft = (id: number) => claims.some((c) => c.personId === id && c.status === 'DRAFT');
  const listed = (people.data ?? []).filter((p) => showRetired || !p.retiredFrom || hasDraft(p.id));

  const change = (patch: Partial<PersonInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  const open = (person: Person) => {
    setEditing(String(person.id));
    setForm({ name: person.name, grade: person.grade ?? 'A', version: person.version });
    setError('');
  };

  const cancel = () => {
    setEditing(undefined);
    setForm(EMPTY);
    setError('');
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!form.name.trim()) {
      setError('A person needs a name.');
      return;
    }
    once(() => save.mutateAsync(form));
  };

  return (
    <section data-testid="people">
      <h2>People</h2>
      <form data-testid="person-form" onSubmit={submit}>
        <input
          data-testid="person-form-name"
          placeholder="Name"
          value={form.name}
          onChange={(e) => change({ name: e.target.value })}
        />
        <select
          data-testid="person-form-grade"
          value={form.grade}
          onChange={(e) => change({ grade: e.target.value })}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
        <input
          type="date"
          data-testid="person-form-grade-from"
          title="Grade from"
          value={form.gradeFrom ?? today ?? ''}
          onChange={(e) => change({ gradeFrom: e.target.value })}
        />
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing ? 'Save' : 'Add person'}
        </button>
        {editing && (
          <button type="button" data-testid="person-form-cancel" onClick={cancel}>
            Cancel
          </button>
        )}
        {error && <span data-testid="person-form-error">{error}</span>}
      </form>
      <PeopleBar.Slot />
      <table data-testid="people-list">
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <PersonColumns.Slot />
            <th />
          </tr>
        </thead>
        <tbody>
          {listed.map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <PersonCells.Slot personId={p.id} />
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 10, Component: People });
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson, putJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';

export const GRADES = ['A', 'B', 'C'] as const;

export type Person = { id: number; name: string;
  /** The grade in force on the sheet's today (null before all their grades). */
  grade: string | null;
  /** Every grade recorded, by from-date (yyyy-mm-dd; null: from the beginning of time). */
  grades: { from: string | null; grade: string }[];
  version: number;
  /** The date retired from (yyyy-mm-dd); null while not retired. A claim dated after it is refused. */
  retiredFrom: string | null;
  /** While on hold, their OPEN claims count in no live total; their SETTLED claims still do. */
  held: boolean;
  /** The ids of the other people on the sheet named as their patrons. */
  patronIds: number[] };
/** An edit carries the version of the person it was loaded from; the server refuses it (409) when
 *  someone else has saved the person since. */
export type PersonInput = { name: string; grade: string; version?: number;
  /** The date the grade applies from (empty: the sheet's today); a person's first grade applies from
   *  the beginning of time. */
  gradeFrom?: string };

/** The person's grade in force on a date (yyyy-mm-dd): the latest from-date on or before it. */
export function gradeOn(person: Person | undefined, date: string | undefined): string | undefined {
  if (person === undefined || date === undefined) return undefined;
  let found: { from: string | null; grade: string } | undefined;
  for (const g of person.grades) {
    if (g.from !== null && g.from > date) continue;
    if (found === undefined || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade;
}

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/people`;
export const peopleKey = (sheet: string) => ['sheet', sheet, 'people'] as const;

/** The active sheet's people, in the order they were added, retired or not (every total counts them). */
export function usePeople() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: peopleKey(sheet ?? ''),
    queryFn: () => getJson<{ people: Person[] }>(base(sheet!)).then((r) => r.people),
    enabled: !!sheet,
  });
}

export const addPerson = (sheet: string, user: string, input: PersonInput) =>
  postJson<Person>(base(sheet), input, user);

export const updatePerson = (sheet: string, user: string, id: number, input: PersonInput) =>
  putJson<Person>(`${base(sheet)}/${id}`, input, user);

/** The outcome of an import: the counts added and updated, or the numbers of the lines refused
 *  (nothing imported). */
export type ImportResult = { added: number; updated: number; errors: number[] };

/** Imports people pasted as lines of name,grade; a refusal (400) carries the bad line numbers. */
/** Retires a person from a date (empty: the sheet's today); refused (400) when already retired. */
export const retirePerson = (sheet: string, user: string, id: number, from: string) =>
  postJson<Person>(`${base(sheet)}/${id}/retire`, { from }, user);

/** Puts a person on hold (held true) or releases them (false); refused (400) when already so. */
export const holdPerson = (sheet: string, user: string, id: number, held: boolean) =>
  postJson<Person>(`${base(sheet)}/${id}/hold`, { held }, user);

/** Names another person on the sheet as the person's patron; refused (400) for themselves or one
 *  already named. */
export const addPatron = (sheet: string, user: string, id: number, patronId: number) =>
  postJson<Person>(`${base(sheet)}/${id}/patrons`, { patronId }, user);

/** Whether a claim dated `date` would be after the person's retirement (and so refused). */
export const afterRetirement = (person: Person | undefined, date: string) =>
  !!person?.retiredFrom && date > person.retiredFrom;

/** Whether retired people are listed too, kept in the URL. */
export const useShowRetired = () => useSearchParam('showRetired', asFlag);

export const importPeople = (sheet: string, user: string, text: string) =>
  postJson<ImportResult>(`${base(sheet)}/import`, { text }, user);

/** The person open in the editor (by id), kept in the URL. */
export const useEditingPerson = () => useSearchParam('editPerson', asString);
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson, putJson } from '../../api/http';
import { useCurrentSheet, useSheetToday } from '../session/session';
import { usePeople } from '../people/people';
import { useFloor, useLatePct, useTerms } from '../settings/settings';
import { claimDueCents } from '../rates/rates';

// Amounts travel as strings with two decimals ("13.50"); sums are added up in whole cents so no
// floating-point error shows.
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  /** Given when opened, the next on the sheet; null for a draft; a voided claim keeps it. */
  number: number | null;
  /** Fixed when settled (two decimals); null while live, or when no rate applied at settling. */
  settledDue: string | null;
  /** The user who opened it; null for a draft. */
  openedBy: string | null;
  /** For a correction (a negative amount), the number of the SETTLED claim it corrects; null otherwise. */
  corrects: number | null };
export type ClaimInput = { amount: string; date: string; note: string; corrects: string };

/** A number with up to two decimals; negative only for a correction. */
export const AMOUNT = /^-?\d+(\.\d{1,2})?$/;

/** A claim number. */
export const NUMBER = /^\d{1,9}$/;

/** Whether an amount is negative, which makes its claim a correction. */
export const isCorrection = (amount: string) => /^-/.test(amount.trim()) && /[1-9]/.test(amount);

/** A correction must name, by number, a SETTLED claim of the same person; any other claim names none. */
export function correctionError(claims: Claim[], personId: number, amount: string, corrects: string): string | undefined {
  const named = corrects.trim();
  if (named !== '' && !NUMBER.test(named)) return 'The claim corrected must be given by its number.';
  if (!isCorrection(amount)) {
    return named === '' ? undefined : 'Only a correction (a negative amount) names a claim it corrects.';
  }
  if (named === '') return 'A negative amount is a correction: name the settled claim it corrects.';
  const target = claims.find((c) => c.number === Number(named));
  if (!target || target.personId !== personId || target.status !== 'SETTLED') {
    return `A correction must name a settled claim of the same person; claim ${named} is not one.`;
  }
  return undefined;
}

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}`;
export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'] as const;

/** The active sheet's claims, newest first. */
export function useClaims() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: claimsKey(sheet ?? ''),
    queryFn: () => getJson<{ claims: Claim[] }>(`${base(sheet!)}/claims`).then((r) => r.claims),
    enabled: !!sheet,
  });
}

export const addClaim = (sheet: string, user: string, personId: number, input: ClaimInput) =>
  postJson<Claim>(`${base(sheet)}/people/${personId}/claims`, input, user);

/** The quick-add bar: a DRAFT claim dated the sheet's today with an empty note, for the named person
 *  (created with grade A when not on the sheet). */
export const quickAddClaim = (sheet: string, user: string, input: { name: string; amount: string }) =>
  postJson<Claim>(`${base(sheet)}/quick-claims`, input, user);

export const updateClaim = (sheet: string, user: string, id: number, input: ClaimInput) =>
  putJson<Claim>(`${base(sheet)}/claims/${id}`, input, user);

// A claim starts DRAFT; it can be opened, then settled; a DRAFT or OPEN claim can be voided.
// SETTLED and VOID are final. The server refuses a change not allowed; the screen refuses it first.
export type ClaimAction = 'open' | 'settle' | 'void';
export const CLAIM_ACTIONS: ClaimAction[] = ['open', 'settle', 'void'];
const ALLOWED: Record<ClaimAction, ClaimStatus[]> = { open: ['DRAFT'], settle: ['OPEN'], void: ['DRAFT', 'OPEN'] };
export const canTake = (claim: Claim, action: ClaimAction) => ALLOWED[action].includes(claim.status);

/** Only a DRAFT can be edited; to change an OPEN claim, void it and add a new one. */
export const canEdit = (claim: Claim) => claim.status === 'DRAFT';

/** Four eyes: the user who opened a claim cannot settle it. */
export const selfSettle = (claim: Claim, user: string, action: ClaimAction) =>
  action === 'settle' && claim.openedBy != null && claim.openedBy === user.trim();

export const claimAction = (sheet: string, user: string, id: number, action: ClaimAction) =>
  postJson<Claim>(`${base(sheet)}/claims/${id}/${action}`, {}, user);

/** Whether a claim counts toward claimed, due-total and every total: only OPEN and SETTLED do. */
export const counts = (claim: Claim) => claim.status === 'OPEN' || claim.status === 'SETTLED';

/** Whether a claim counts toward the live totals: as `counts`, except that the OPEN claims of a person
 *  on hold count in none (their SETTLED claims still do). */
export function useCounts() {
  const held = new Set((usePeople().data ?? []).filter((p) => p.held).map((p) => p.id));
  return (claim: Claim) => counts(claim) && !(claim.status === 'OPEN' && held.has(claim.personId));
}

const cents = (amount: string) => {
  const negative = amount.startsWith('-');
  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
  const n = Number(whole) * 100 + Number((frac + '00').slice(0, 2));
  return negative ? -n : n;
};

/** The amounts of the claims that count (by `counted`, from `useCounts`) added up, shown with two decimals. */
export function total(claims: Claim[], counted: (claim: Claim) => boolean): string {
  const sum = claims.filter(counted).reduce((n, c) => n + cents(c.amount), 0);
  const abs = Math.abs(sum);
  return `${sum < 0 ? '-' : ''}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}

/** A date (yyyy-mm-dd) plus a number of days, as yyyy-mm-dd. */
export function addDays(date: string, days: number): string {
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
}

/** A claim's due-by: its date plus the sheet's terms in force (days). */
export function useDueBy() {
  const terms = useTerms();
  return (claim: Claim) => addDays(claim.date, terms);
}

/** Whether a claim is overdue: it is OPEN and its due-by is before the sheet's today. */
export function useOverdue() {
  const dueBy = useDueBy();
  const today = useSheetToday();
  return (claim: Claim) => claim.status === 'OPEN' && today !== undefined && dueBy(claim) < today;
}

/** Whole days from one date (yyyy-mm-dd) to another. */
export function daysBetween(from: string, to: string): number {
  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86400000);
}

/** A claim's due in cents (see `claimDueCents`) at a rate, with the sheet's floor and, while it is overdue,
 *  the late percent for each full 30 days past its due-by. */
export function useClaimDue() {
  const floor = useFloor();
  const latePct = useLatePct();
  const dueBy = useDueBy();
  const overdue = useOverdue();
  const today = useSheetToday();
  return (claim: Claim, rate: string | undefined) => {
    const spans = overdue(claim) && today !== undefined ? BigInt(Math.floor(daysBetween(dueBy(claim), today) / 30)) : 0n;
    return claimDueCents(claim, rate, floor, latePct, spans);
  };
}
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { usePeople } from '../people/people';
import { show, usePersonRate } from '../rates/rates';
import { useCurrentSheet } from '../session/session';
import { useClaimDue, useClaims, useCounts, useOverdue } from './claims';

function OverdueColumns() {
  return (
    <>
      <th>Overdue</th>
      <th>Overdue total</th>
    </>
  );
}

/** A person's overdue claims that count: how many, and their dues added up in cents (n/a as 0). */
function useOverdueOf() {
  const claims = useClaims().data ?? [];
  const counts = useCounts();
  const overdue = useOverdue();
  const rateOf = usePersonRate();
  const claimDue = useClaimDue();
  return (personId: number) => {
    const late = claims.filter((c) => c.personId === personId && counts(c) && overdue(c));
    const due = late.reduce((n, c) => n + (claimDue(c, rateOf(personId, c.date)) ?? 0n), 0n);
    return { count: late.length, due };
  };
}

// A person's overdue count and overdue-total: their OPEN claims that count, due by before the sheet's today.
function PersonOverdue({ personId }: { personId: number }) {
  const { count, due } = useOverdueOf()(personId);
  return (
    <>
      <td data-testid="person-overdue-count">{count}</td>
      <td data-testid="person-overdue-total">{show(due)}</td>
    </>
  );
}

// The sheet's overdue count and overdue-total: everyone's added up.
function OverdueTotal() {
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const overdueOf = useOverdueOf();
  if (!sheet) return null;
  const all = people.map((p) => overdueOf(p.id));
  return (
    <section data-testid="rollup-overdue">
      Overdue <strong data-testid="rollup-overdue-count">{all.reduce((n, o) => n + o.count, 0)}</strong>{' '}
      Overdue total <strong data-testid="rollup-overdue-total">{show(all.reduce((n, o) => n + o.due, 0n))}</strong>
    </section>
  );
}

export const contributions = [
  PersonColumns.fill({ order: 30, Component: OverdueColumns }),
  PersonCells.fill({ order: 30, Component: PersonOverdue }),
  HomeMain.fill({ order: 22, Component: OverdueTotal }),
];

