import { useState } from 'react';
import type { FormEvent } from 'react';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HomeMain } from '../../slots/defs/homeMain';
import { useClaimDue, useClaims, useCounts } from '../claims/claims';
import { hundredths, show, usePersonRate } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { addPeriod, closePeriod, periodsKey, reopenPeriod, usePeriods } from './periods';
import type { Period, PeriodInput } from './periods';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

const EMPTY: PeriodInput = { name: '', from: '', to: '' };

/** A period's due-total in cents: once closed, the one fixed then; otherwise the due of the claims that
 *  count whose date falls in it (n/a as 0). */
function usePeriodDue() {
  const claims = useClaims().data ?? [];
  const rateOf = usePersonRate();
  const counts = useCounts();
  const claimDue = useClaimDue();
  return (period: Period) =>
    period.closed && period.closedTotal !== null
      ? hundredths(period.closedTotal)
      : claims
      .filter((c) => counts(c) && period.from <= c.date && c.date <= period.to)
      .reduce((n, c) => n + (claimDue(c, rateOf(c.personId, c.date)) ?? 0n), 0n);
}

// The sheet's periods: a form that adds one (a name unique on the sheet, from on or before to, not
// overlapping another), and each period with its dates, its due-total, whether it is closed and a button
// that closes it, and one that reopens it (a closed period, by a steward only). A refused close or reopen
// shows on its period.
function Periods() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const periods = usePeriods().data ?? [];
  const dueOf = usePeriodDue();
  const [form, setForm] = useState<PeriodInput>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();
  const [periodErrors, setPeriodErrors] = useState<Record<string, string>>({});

  const close = useMutation({
    mutationFn: (name: string) => closePeriod(sheet!, user, name),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) }),
    onError: async (_e, name) => {
      setPeriodErrors((e) => ({ ...e, [name]: `The period ${name} could not be closed.` }));
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) });
    },
  });

  const reopen = useMutation({
    mutationFn: (name: string) => reopenPeriod(sheet!, user, name),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) }),
    onError: async (_e, name) => {
      setPeriodErrors((e) => ({ ...e, [name]: `The period ${name} could not be reopened: only a steward can reopen a closed period.` }));
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) });
    },
  });

  const takeReopen = (period: Period) => {
    setPeriodErrors(({ [period.name]: _, ...rest }) => rest);
    if (!period.closed) {
      setPeriodErrors((e) => ({ ...e, [period.name]: `The period ${period.name} is not closed.` }));
      return;
    }
    reopen.mutate(period.name);
  };

  const take = (period: Period) => {
    setPeriodErrors(({ [period.name]: _, ...rest }) => rest);
    if (period.closed) {
      setPeriodErrors((e) => ({ ...e, [period.name]: `The period ${period.name} is already closed.` }));
      return;
    }
    close.mutate(period.name);
  };

  const save = useMutation({
    mutationFn: (input: PeriodInput) => addPeriod(sheet!, user, input),
    onSuccess: async () => {
      setForm(EMPTY);
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) });
    },
    onError: async () => {
      setError('The period could not be added: its name must be new on the sheet and its dates must not overlap another period.');
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) });
    },
  });

  if (!sheet) return null;

  const change = (patch: Partial<PeriodInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const name = form.name.trim();
    const from = form.from.trim();
    const to = form.to.trim();
    if (name === '') {
      setError('The period must have a name.');
      return;
    }
    if (!DATE.test(from) || !DATE.test(to)) {
      setError('The from and to dates must be dates (yyyy-mm-dd).');
      return;
    }
    if (to < from) {
      setError('The to-date must be on or after the from-date.');
      return;
    }
    if (periods.some((p) => p.name === name)) {
      setError(`A period named ${name} is already on the sheet.`);
      return;
    }
    const clash = periods.find((p) => p.from <= to && from <= p.to);
    if (clash) {
      setError(`The period overlaps ${clash.name}.`);
      return;
    }
    once(() => save.mutateAsync({ name, from, to }));
  };

  return (
    <section data-testid="periods">
      <h2>Periods</h2>
      <form data-testid="period-form" onSubmit={submit}>
        <input
          data-testid="period-form-name"
          placeholder="Name"
          value={form.name}
          onChange={(e) => change({ name: e.target.value })}
        />
        <input
          data-testid="period-form-from"
          type="date"
          value={form.from}
          onChange={(e) => change({ from: e.target.value })}
        />
        <input
          data-testid="period-form-to"
          type="date"
          value={form.to}
          onChange={(e) => change({ to: e.target.value })}
        />
        <button type="submit" data-testid="period-form-submit" disabled={save.isPending}>
          Add period
        </button>
        {error && <span data-testid="period-form-error">{error}</span>}
      </form>
      <table data-testid="period-list">
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Due</th>
            <th>Closed</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td data-testid="period-due-total">{show(dueOf(p))}</td>
              <td data-testid="period-closed">{p.closed ? 'yes' : 'no'}</td>
              <td>
                <button type="button" data-testid="period-close" onClick={() => take(p)}>
                  Close
                </button>
                <button type="button" data-testid="period-reopen" onClick={() => takeReopen(p)}>
                  Reopen
                </button>
                {periodErrors[p.name] && <span data-testid="period-error">{periodErrors[p.name]}</span>}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contributions = [HomeMain.fill({ order: 6, Component: Periods })];
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';

// A period is a name, unique on the sheet, and a from and to date (yyyy-mm-dd), inclusive; no two
// periods of a sheet overlap. A claim belongs to the period whose dates contain its date, or to none.
// A period may be closed: its due-total is then the one fixed when it was closed (closedTotal), and
// no claim dated inside it can be added, edited, opened, settled or voided.
// A steward may reopen a closed period, making its due-total live again.
export type Period = { name: string; from: string; to: string; closed: boolean; closedTotal: string | null };
export type PeriodInput = { name: string; from: string; to: string };

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/periods`;
export const periodsKey = (sheet: string) => ['sheet', sheet, 'periods'] as const;

/** The active sheet's periods, by from-date. */
export function usePeriods() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: periodsKey(sheet ?? ''),
    queryFn: () => getJson<{ periods: Period[] }>(base(sheet!)).then((r) => r.periods),
    enabled: !!sheet,
  });
}

export const addPeriod = (sheet: string, user: string, input: PeriodInput) => postJson<Period>(base(sheet), input, user);

export const closePeriod = (sheet: string, user: string, name: string) =>
  postJson<Period>(`${base(sheet)}/${encodeURIComponent(name)}/close`, {}, user);

export const reopenPeriod = (sheet: string, user: string, name: string) =>
  postJson<Period>(`${base(sheet)}/${encodeURIComponent(name)}/reopen`, {}, user);

/** The period whose dates contain the date, or undefined. */
export const periodOf = (periods: Period[], date: string): Period | undefined =>
  periods.find((p) => p.from <= date && date <= p.to);

/** The name of the period a date (yyyy-mm-dd) falls in on the active sheet, or undefined. */
export function usePeriodOf() {
  const periods = usePeriods().data ?? [];
  return (date: string) => periodOf(periods, date)?.name;
}

/** The closed period a date (yyyy-mm-dd) falls in on the active sheet, or undefined. */
export function useClosedPeriodOf() {
  const periods = usePeriods().data ?? [];
  return (date: string) => {
    const p = periodOf(periods, date);
    return p?.closed ? p : undefined;
  };
}

